export function activeJournalQuests(s){
 const campaign=campaignView(s),rows=[];
 for(const q of campaign.quests.filter(q=>q.status==='active'&&(q.id.startsWith('side_')?s.questLog?.entries[q.id]?.status==='active':s.questLog?.main==='active')))rows.push({...q,key:q.id.startsWith('side_')?q.id:'main',kind:'main'});
 for(const c of (adventureView(s)?.contracts||[]).filter(c=>['active','ready'].includes(c.status)))rows.push({...c,key:'radiant:'+c.id,kind:'contract',abandonId:'adventure_abandon_'+c.id,paused:Boolean(c.paused),status:c.paused?'paused':c.status,resumeId:c.paused?'journal_resume_radiant:'+c.id:null,pauseId:!c.paused?'journal_pause_radiant:'+c.id:null,locationId:c.status==='ready'?c.boardId:c.destinationId,objective:c.status==='ready'?`Return to ${c.giver.name} for payment.`:c.brief,description:c.status==='ready'?`${c.reward} Gold owed for this completed job.`:`${c.reward} Gold on completion.`,personName:c.giver.name});
 const favors=(s.socialLife?.favors||[]).filter(f=>f.status==='active').map(f=>({key:f.id,kind:'favour',title:'Supplies for '+f.name,personName:f.name,locationId:f.locationId,objective:'Bring 2 '+f.item+' to '+f.name+'.',description:'12 Gold on delivery.'+(f.returnWindow?` Their public retirement is recorded. The saved one-time return window ends on world day ${f.returnWindow.untilDay}; current availability still matters. ${s.day>f.returnWindow.untilDay?'Their later whereabouts are unrecorded. ':''}Withdrawal remains possible without losing supplies, Gold or trust.`:''),withdrawActionId:'people_withdraw_'+f.personId,deliverActionId:'people_deliver_'+f.personId}));
 const mazes=[s.maze,...(s.mazeBook?.records||[])].filter(Boolean).filter((m,i,a)=>a.findIndex(x=>x.id===m.id)===i).filter(m=>!m.objective).map(m=>({key:m.id,kind:'exploration',title:m.title,locationId:m.locationId,objective:'Find the deep chamber, complete its objective, and return through a stair.',description:m.visited.length+' rooms explored. Discovered passages remain saved.'}));
 return [...rows.map(q=>({...q,...groundedQuest(s,q,{kind:q.kind})})),...favors,...mazes,...regionalQuestRows(s),...intrigueJournalRows(s),...journalCommitments(s)];
}
export const JOURNAL_CATEGORIES=[['all','All'],['main','Main'],['side','Side'],['misc','Errands & exploration'],['radiant','Repeatable work'],['commitments','Commitments']];
export function journalQuestCategory(q){return q.commitment?'commitments':q.key?.startsWith('radiant:')||q.kind==='contract'?'radiant':q.id?.startsWith('side_')?'side':q.kind==='main'?'main':q.kind==='personal'?'side':'misc';}
export function offeredJournalQuests(s,actions){
 const campaign=campaignView(s),rows=[],main=campaign.quests.find(q=>!q.id.startsWith('side_')&&!['completed','locked'].includes(q.status));
 if(main&&s.questLog?.main==='offered'&&actions.some(a=>a.id==='journal_main_accept'))rows.push({...main,key:'main',kind:'main',accept:'journal_main_accept'});
 for(const q of campaign.quests.filter(q=>q.id.startsWith('side_')&&!['completed','locked'].includes(q.status)&&questEntryStatus(s,q.id)==='offered'))if(actions.some(a=>a.id==='journal_accept_'+q.id))rows.push({...q,key:q.id,kind:'side',accept:'journal_accept_'+q.id});
 for(const q of storyInvitations(s)){const reconsider=actions.some(a=>a.id==='stories_reconsider_'+q.id),accept=(reconsider?'stories_reconsider_':'stories_open_')+q.id,decline=actions.some(a=>a.id==='stories_decline_'+q.id)?'stories_decline_'+q.id:null;if(actions.some(a=>a.id===accept))rows.push({...q,key:'invitation:'+q.id,kind:'personal',accept,decline,reconsider,review:!reconsider,objective:q.premise});}
 return rows;
}
export function renderSimpleJournal(s,actions,ui,{query='',pages={},personalScope='current',noteDraft,category='all'}={}){
 const {e,button,paragraphs,date}=ui,section=ui.section||'active',matches=r=>!query||[r.title,r.text,r.objective,r.client,r.boardName,r.destinationName,r.proof?.method,...(r.attempts||[]).map(a=>a.outcome),r.personName,r.description,r.summary,r.result,s.world.locations.find(p=>p.id===r.locationId)?.name,...(r.choices||[]).map(c=>c.outcome),...(r.details||[])].join(' ').toLowerCase().includes(query.toLowerCase());
 const search=`<form id="journal-search" class="journal-search"><label class="sr-only" for="journal-query">Search Journal</label><input id="journal-query" name="query" type="search" value="${e(query)}" placeholder="Search Journal"><button type="submit" class="button secondary small">Search</button>${query?button('Clear Search','journal-clear','','ghost small'):''}</form><p class="small-copy journal-search-scope">${section==='notes'?'Search discoveries and personal notes. Remembered night invitations are shown separately.':section==='active'?'Search active quests, commitments and offers in this category.':'Search finished quests and recorded life entries.'}</p>`;
 let content='';
 if(section==='active'){
 const allowed=JOURNAL_CATEGORIES.some(([id])=>id===category)?category:'all',inCategory=q=>allowed==='all'||journalQuestCategory(q)===allowed;
 const unfiltered=activeJournalQuests(s),scoped=unfiltered.filter(inCategory),all=scoped.filter(matches),rows=all.filter(q=>!q.commitment),offers=offeredJournalQuests(s,actions).filter(inCategory).filter(matches),offersPage=journalPage(offers,pages.offers),tracked=trackedQuest(s);
 const categories=`<nav class="journal-categories" aria-label="Quest categories">${JOURNAL_CATEGORIES.map(([id,label])=>button(label,'journal-category',id,'ghost small',false,allowed===id)).join('')}</nav>`;
 const tracking=tracked?`<aside class="quest-tracker"><span class="eyebrow">TRACKED QUEST</span><strong>${e(tracked.title)}</strong><p>${e(tracked.objective)}</p>${tracked.locationId?button('Show destination','quest-location',tracked.locationId,'ghost small'):''}${actions.some(a=>a.id==='journal_clear_track')?button('Clear tracking','activity','journal_clear_track','ghost small'):''}<p class="small-copy">Clearing tracking keeps the quest accepted.</p></aside>`:'';
 const invitations=offers.length?`<section class="journal-offers"><h2>Offers · not accepted</h2>${renderJournalPager(offersPage,'offers','Offers',ui,{total:offers.length,query})}${offersPage.rows.map(q=>{const a=actions.find(a=>a.id===q.accept),place=s.world.locations.find(p=>p.id===q.locationId);return `<article class="journal-quest"${q.kind==='personal'?` data-invitation="${e(q.id)}"`:''}><h3>${e(q.title)}</h3>${paragraphs(q.description||q.objective)}${place?`<p class="small-copy">${e(place.name)}</p>`:''}${button(q.reconsider?'Reconsider invitation':q.review?'Hear the proposal':'Accept this quest','activity',q.accept,'secondary small',!!a?.disabledReason)}${q.decline?button('Decline invitation','activity',q.decline,'ghost small',Boolean(actions.find(a=>a.id===q.decline)?.disabledReason)):''}${a?.disabledReason?`<p class="disabled-reason">${e(a.disabledReason)}</p>`:''}<p class="small-copy">${q.reconsider?'Reconsidering restores an offer; it accepts no work.':q.review?'Reading accepts no work. Review its terms, decide later or leave.':'Accepting records the quest. Travel and later actions keep their separately quoted days and costs.'}</p></article>`;}).join('')}</section>`:'';
 const results=`<p id="journal-active-results" tabindex="-1" data-view-results>Active quests and commitments: ${all.length}${query||allowed!=='all'?` matching / ${unfiltered.length} recorded`:' recorded'}. ${e(JOURNAL_CATEGORIES.find(([id])=>id===allowed)[1])} category.</p>`;
 const commitments=renderJournalCommitments(s,all.filter(q=>q.commitment),actions,ui,{searching:Boolean(query)});
 content=categories+tracking+results+(['all','side'].includes(allowed)?renderOriginInvitation(s,actions,ui,{query}):'')+commitments+(rows.map(q=>{const p=s.world.locations.find(p=>p.id===q.locationId),track=actions.find(a=>a.id==='journal_track_'+q.key);return `<article class="journal-quest"><header><h2>${e(q.title)}</h2>${s.questLog?.tracked===q.key?'<span class="badge">Tracked</span>':''}${q.paused?'<span class="badge">Paused</span>':''}</header>${q.personName?`<p class="quest-giver">${e(q.personName)}</p>`:''}${paragraphs(q.objective||q.description)}${q.description&&q.objective?`<p class="small-copy">${e(q.description)}</p>`:''}<div class="quick-actions">${q.resumeId&&actions.some(a=>a.id===q.resumeId)?button('Resume contract','activity',q.resumeId,'secondary small',Boolean(actions.find(a=>a.id===q.resumeId)?.disabledReason)):''}${q.pauseId&&actions.some(a=>a.id===q.pauseId)?button('Pause contract','activity',q.pauseId,'ghost small',Boolean(actions.find(a=>a.id===q.pauseId)?.disabledReason)):''}${q.abandonId&&actions.some(a=>a.id===q.abandonId)?button('Abandon contract','activity',q.abandonId,'ghost small',Boolean(actions.find(a=>a.id===q.abandonId)?.disabledReason)):''}${q.actionId&&actions.some(a=>a.id===q.actionId)?button('Read the next letter','activity',q.actionId,'secondary small',Boolean(actions.find(a=>a.id===q.actionId)?.disabledReason)):''}${q.deliverActionId&&actions.some(a=>a.id===q.deliverActionId)?button('Deliver supplies','activity',q.deliverActionId,'secondary small',Boolean(actions.find(a=>a.id===q.deliverActionId)?.disabledReason)):''}${q.withdrawActionId&&actions.some(a=>a.id===q.withdrawActionId)?button('Withdraw favour','activity',q.withdrawActionId,'ghost small',Boolean(actions.find(a=>a.id===q.withdrawActionId)?.disabledReason)):''}${p?button('Find '+e(p.name),'quest-location',p.id,'secondary small'):''}${track?button('Track','activity',track.id,'ghost small',Boolean(track.disabledReason)):''}</div></article>`;}).join('')||(commitments?'':`<section class="journal-empty"><h2>${query?'No Active Quests Match This Search':'No Active Quests'}</h2><p>${query?'Clear the search to see your recorded quests and commitments.':'Explore a settlement and speak with people. Accept the work that interests you; it will appear here.'}</p></section>`))+invitations;
 }else if(section==='archive'){
 const finished=[...campaignView(s).quests.filter(q=>q.status==='completed'),...contractArchive(s).map(q=>({...q,receiptKind:'contract'})),...(storyView(s)?.arcs||[]).filter(a=>['completed','abandoned'].includes(a.status)),...(s.rpg?.arcs||[]).filter(a=>['completed','abandoned'].includes(a.status))].map(q=>q.receiptKind==='contract'?q:({...q,...groundedQuest(s,q,{kind:'archive'})}));
 finished.push(...(s.socialLife?.favors||[]).filter(f=>['completed','withdrawn'].includes(f.status)).map(f=>({title:'Supplies for '+f.name,result:f.status==='completed'?'Delivered 2 '+f.item+' for 12 Gold.':'Withdrawn without supplies, Gold or trust changing hands.'})),...(s.mazeBook?.records||[]).filter(m=>m.objective).map(m=>({title:m.title,result:'Objective completed; '+m.visited.length+' rooms explored.'})));
 finished.push(...firstMissionArchiveRows(s),...countingTableJournalRows(s,{archive:true}),...regionalQuestRows(s,{archive:true}),...intrigueJournalRows(s,{archive:true}));
 const memories=[...s.journal].reverse().filter(matches),memoryPage=journalPage(memories,pages.life),finishedPage=journalPage(finished.filter(matches),pages.finished);
 content=renderClosingAccounts(s,ui)+renderResearchArchive(s,ui,{query})+renderOriginArchive(s,ui,{query})+renderExpeditionReceiptArchive(s,ui,{query})+`${finished.length?`<section class="quest-archive"><h2>Finished Quests</h2>${renderJournalPager(finishedPage,'finished','Finished quests',ui,{total:finished.length,query})}${finishedPage.rows.map(q=>q.receiptKind==='contract'?renderContractReceipt(q,ui):`<article class="remembered-entry"><h3>${e(q.title)}</h3><span class="badge">${e(undertakingStatusLabel(q.status||q.result))}</span><p>${e(q.choices?.at(-1)?.outcome||q.objective||q.summary||q.result||'Completed')}</p>${renderStoryDecisions(q,ui)}</article>`).join('')}</section>`:''}<section class="journal-memories"><h2>Your Life</h2>${renderJournalPager(memoryPage,'life','Life entries',ui,{total:s.journal.length,query})}${memoryPage.rows.map(r=>`<article class="remembered-entry"><small>${e(date(r.day))} · Age ${r.age}</small><h3>${e(r.title)}</h3>${paragraphs(r.text)}</article>`).join('')||(query?'<p>No life entries match this search.</p>':'<p>No earlier moments have been recorded.</p>')}${button('Export Your Life','export','','ghost small')}</section>`;
 }else{
 const innNotes=Object.entries(s.hospitality?.sites||{}).filter(([,r])=>r.rumor).map(([id,r])=>({title:'Word at the Inn — '+(s.world.locations.find(p=>p.id===id)?.name||id),text:r.rumor.text}));
 const ownNotes=personalNoteRows(s).filter(n=>n.own),v=loreView(s),allNotes=[...v.histories.filter(n=>n.discovered),...v.rumors.filter(n=>n.discovered),...v.records].map(n=>({...n,...groundedNote(s,n)})).concat(regionalNotes(s),innNotes,repertoireJournalRows(s)),notes=allNotes.filter(matches),notePage=journalPage(notes,pages.discoveries);
 content=`<section class="journal-notes"><div class="journal-notes-entry"><div><h2 id="journal-discoveries-heading" tabindex="-1">Notes & Discoveries</h2><p id="journal-discovery-results" data-view-results>Discoveries: ${notes.length}${query?` matching / ${allNotes.length} recorded`:' recorded'}.</p><p>Personal Notes: ${ownNotes.filter(n=>!n.archived).length} current · ${ownNotes.filter(n=>n.archived).length} archived.</p></div>${button(noteDraft?.text?'Resume Note':'Write Note','personal-note-write','','secondary')}</div><p>The things you have learned from people, places and books.</p>${renderJournalPager(notePage,'discoveries','Discoveries',ui,{total:allNotes.length,query})}${notePage.rows.map(n=>`<article class="remembered-entry"><h3>${e(n.title)}</h3>${paragraphs(n.text)}</article>`).join('')||(query?'<p>No discoveries match this search. Clear the search to restore your discoveries.</p>':'<p>Your notebook is still empty. Ask questions and investigate the places you find.</p>')}${supernaturalNotes(s,ui,[],{readOnly:true})||''}</section>${renderPersonalNotes(s,ui,{query,page:pages.personal,scope:personalScope,draft:noteDraft})}`;
 }
 return `<div class="journal-workspace simple-journal"><header><span class="eyebrow">YOUR JOURNEY</span><h1>Journal</h1></header>${search}${content}</div>`;
}
